mapper.codeEditorJavascript:
const L=typeof input.l==='string'?JSON.parse(input.l):(input.l||[]);
let want=[];try{want=JSON.parse(input.data||'[]')}catch(e){}
const age=Number(input.age||0);
const norm=p=>{p=String(p||'').replace(/\D/g,'');if(p.startsWith('972'))p='0'+p.slice(3);return p;};
const set=new Map();for(const w of want){const p=norm(w.p);if(p)set.set(p,Math.max(10,Math.min(100,Math.round(w.pr))));}
const out=[];let aged=0;
for(const x of L){const p=norm(x.displayPhone);if(!p)continue;
 if(set.has(p)){if(set.get(p)!==x.priority)out.push({phone:p,pr:set.get(p)});set.delete(p);continue;}
 if(age>0&&x.status==='PENDING'){const np=Math.min(100,(x.priority||50)+age);if(np!==x.priority){out.push({phone:p,pr:np});aged++;}}}
return {items:out,n:out.length,aged,missing:[...set.keys()].length,open:L.length};
